'use client';

import { FormEvent, PointerEvent, useEffect, useMemo, useRef, useState } from 'react';

type Role = 'employee' | 'leader' | 'hr';
type PageId = 'dashboard' | 'attendance' | 'tasks' | 'virtual-office' | 'leave' | 'team' | 'approvals' | 'employees' | 'profile' | 'settings';
type ModalId = 'announcement' | 'announcement-detail' | 'leave' | 'task' | 'people' | 'photo-checkin' | 'meeting-a' | 'meeting-b' | 'lounge' | 'work' | 'review-reason' | null;

const basePages = [
  ['dashboard', 'Dashboard'], ['attendance', 'Attendance'], ['tasks', 'Tasks'],
  ['virtual-office', 'Virtual Office'], ['leave', 'Leave'], ['team', 'Team'],
] as const;
const roleName = (role: Role) => role === 'leader' ? 'Team Leader' : role === 'hr' ? 'HR' : 'Employee';
const demoAccounts = [
  ['Beau','demo@komorebi.local','employee'], ['Night','leader@komorebi.local','leader'], ['Aom','hr@komorebi.local','hr'],
  ['Mina','mina@komorebi.local','employee'], ['Rin','rin@komorebi.local','employee'], ['Ploy','ploy@komorebi.local','employee'],
  ['Jay','jay@komorebi.local','employee'], ['Nara','nara@komorebi.local','employee'],
] as const;
const demoPassword='Demo1234!';
type AnnouncementNote=[string,string,string,string,string];

type IconName = 'brand' | 'bell' | 'clock' | 'check-in' | 'check-out';
